def verify_isbn(isbn):
    # Check if the input is a string
    if not isinstance(isbn, str):
        raise ValueError("ISBN must be a string")

    # Remove the hyphens from the input string
    isbn = isbn.replace("-", "")

    # Check if the input has the correct length
    if len(isbn) != 10:
        raise ValueError("ISBN must be 10 digits long")

    # Calculate the checksum using the last digit
    checksum = 0
    for i in range(9):
        checksum += int(isbn[i]) * (10-i)
    calculated_checksum = 11 - (checksum % 11)

    # Check if the checksum is correct
    if calculated_checksum == 10:
        calculated_checksum = "X"
    elif calculated_checksum == 11:
        calculated_checksum = "0"

    # Check if the input has the correct format for an ISBN
    if isbn[:9] != "978" or isbn[9] not in "0123456789X":
        raise ValueError("Invalid ISBN format")

    # Verify the checksum and return the right output
    if calculated_checksum == isbn[9]:
        return "Right"
    else:
        return isbn[:9] + calculated_checksum

def count_passing_ways(n: int, m: int) -> int:
    """
    Counts the number of different ways to pass a ball among 'n' students arranged in a circle
    such that after 'm' passes, the ball returns to the starting student.

    The function uses dynamic programming to determine the number of passing sequences. Each student
    can pass the ball either to the left neighbor or to the right neighbor.

    Args:
    n: The number of students standing in a circle.
    m: The number of times the ball is passed.

    Returns:
    An integer representing the number of distinct passing ways that result in the ball
    returning to the starting student after 'm' passes.

    Cases:
    >>> count_passing_ways(3, 3)
    2
    >>> count_passing_ways(5, 4)
    6
    """
    memo = {}
    def count_ways(i, j, count=0):
        if (i, j) in memo:
            return memo[i, j]
        if i == j:
            return 0
        if j == (i - 1) % n:
            return 1
        if i == 0 and j == n - 1:
            return 1
        if i == j + 1:
            return count_ways(i, j, count + 1)
        return count_ways(i, j - 1, count) + count_ways(i, j + 1, count)
    return count_ways(0, n - 1)

def count_partitions(n: int, k: int, x: int) -> int:
    """
    Count the number of ways to partition an integer n into k parts,
    where each part is at least x and order of parts does not matter.
    """
    if n < k * x:
        return 0
    if k == 1:
        return 1
    if x == 1:
        return n
    return sum(count_partitions(n - i * x, k - 1, x) for i in range(x, n + 1))

